73	inline bool RayTriangleIntersection(const vec3& orig,
74	                                    const vec3& dir,
75	                                    const vec3& v0,
76	                                    const vec3& v1,
77	                                    const vec3& v2,
78	                                    float& t,
79	                                    float& u,
80	                                    float& v)
81	{
82	    const float EPSILON = 1e-6f;
83	    vec3 e1 = v1 - v0;
84	    vec3 e2 = v2 - v0;
85	    vec3 pvec = glm::cross(dir, e2);
86	    float det = glm::dot(e1, pvec);
87	    if (fabs(det) < EPSILON)
88	        return false;
89	
90	    float invDet = 1.0f / det;
91	    vec3 tvec = orig - v0;
92	    u = glm::dot(tvec, pvec) * invDet;
93	    if (u < 0.0f || u > 1.0f)
94	        return false;
95	
96	    vec3 qvec = glm::cross(tvec, e1);
97	    v = glm::dot(dir, qvec) * invDet;
98	    if (v < 0.0f || u + v > 1.0f)
99	        return false;
100	
101	    t = glm::dot(e2, qvec) * invDet;
102	    return t > 0.0f;
103	}
