105	// Manual BMP writer from vec3 pixel array (row-major, top-to-bottom)
106	static void SaveBMPFromPixels(const char* path, const std::vector<glm::vec3>& pixels, int w, int h)
107	{
108	    int row_pad = (4 - (w * 3) % 4) % 4;
109	    int img_size = (w * 3 + row_pad) * h;
110	    int file_size = 54 + img_size;
111	
112	    unsigned char header[54] = {};
113	    header[0] = 'B'; header[1] = 'M';
114	    header[2] = file_size; header[3] = file_size >> 8;
115	    header[4] = file_size >> 16; header[5] = file_size >> 24;
116	    header[10] = 54;
117	    header[14] = 40;
118	    header[18] = w; header[19] = w >> 8; header[20] = w >> 16; header[21] = w >> 24;
119	    header[22] = h; header[23] = h >> 8; header[24] = h >> 16; header[25] = h >> 24;
120	    header[26] = 1;
121	    header[28] = 24;
122	    header[34] = img_size; header[35] = img_size >> 8;
123	    header[36] = img_size >> 16; header[37] = img_size >> 24;
124	
125	    std::ofstream f(path, std::ios::binary);
126	    if (!f) { cerr << "SaveBMP: cannot open " << path << endl; return; }
127	
128	    f.write(reinterpret_cast<char*>(header), 54);
129	
130	    unsigned char pad[3] = {0, 0, 0};
131	    // BMP stores bottom-to-top
132	    for (int y = h - 1; y >= 0; --y) {
133	        for (int x = 0; x < w; ++x) {
134	            const glm::vec3& c = pixels[y * w + x];
135	            unsigned char r = (unsigned char)glm::clamp(c.r * 255.0f, 0.0f, 255.0f);
136	            unsigned char g = (unsigned char)glm::clamp(c.g * 255.0f, 0.0f, 255.0f);
137	            unsigned char b = (unsigned char)glm::clamp(c.b * 255.0f, 0.0f, 255.0f);
138	            unsigned char bgr[3] = {b, g, r};
139	            f.write(reinterpret_cast<char*>(bgr), 3);
140	        }
141	        if (row_pad) f.write(reinterpret_cast<char*>(pad), row_pad);
142	    }
143	
144	    f.close();
145	    cout << "Screenshot saved: " << path << " (" << w << "x" << h << ")" << endl;
146	}
