148	// Fallback BMP writer from SDL surface (for CPU path)
149	static void SaveBMP(const char* path, SDL_Surface* surf)
150	{
151	    if (!surf) { cerr << "SaveBMP: null surface" << endl; return; }
152	
153	    int w = surf->w, h = surf->h;
154	    std::vector<glm::vec3> pixels(w * h);
155	
156	    if (SDL_MUSTLOCK(surf)) SDL_LockSurface(surf);
157	    for (int y = 0; y < h; ++y) {
158	        for (int x = 0; x < w; ++x) {
159	            Uint32 pixel = *((Uint32*)((Uint8*)surf->pixels + y * surf->pitch) + x);
160	            Uint8 r, g, b;
161	            SDL_GetRGB(pixel, surf->format, &r, &g, &b);
162	            pixels[y * w + x] = glm::vec3(r / 255.0f, g / 255.0f, b / 255.0f);
163	        }
164	    }
165	    if (SDL_MUSTLOCK(surf)) SDL_UnlockSurface(surf);
166	
167	    SaveBMPFromPixels(path, pixels, w, h);
168	}
