330	void *img_thread(void *arg)
331	{
332	    int area = *(int*)arg;
333	    unsigned int seed = (unsigned int)(area + 1) * 12345;
334	
335	    vec3 black(0.0f, 0.0f, 0.0f);
336	    Intersection intersection, mirror_intersec;
337	    vec3 d, light_area, mirror_shadow, intersection_pos, sum_colour, pixel_colour, sub_pixel;
338	    mat3 R(cos(yaw), 0, sin(yaw), 0, 1, 0, -sin(yaw), 0, cos(yaw));
339	    float x, y, focal_x, focal_y;
340	    int height = 0;
341	    float srceen_width = SCREEN_WIDTH;
342	    float screen_height = SCREEN_HEIGHT;
343	    vec3 original_img[10][10];
344	    int x_value, y_value;
345	
346	    switch (area)
347	    {
348	    case 0: x_value = 0;                y_value = 0;                break;
349	    case 1: x_value = SCREEN_WIDTH / 3; y_value = 0;                break;
350	    case 2: x_value = SCREEN_WIDTH / 3 * 2; y_value = 0;           break;
351	    case 3: x_value = 0;                y_value = SCREEN_HEIGHT / 3; break;
352	    case 4: x_value = SCREEN_WIDTH / 3; y_value = SCREEN_HEIGHT / 3; break;
353	    case 5: x_value = SCREEN_WIDTH / 3 * 2; y_value = SCREEN_HEIGHT / 3; break;
354	    case 6: x_value = 0;                y_value = SCREEN_HEIGHT / 3 * 2; break;
355	    case 7: x_value = SCREEN_WIDTH / 3; y_value = SCREEN_HEIGHT / 3 * 2; break;
356	    case 8: x_value = SCREEN_WIDTH / 3 * 2; y_value = SCREEN_HEIGHT / 3 * 2; break;
357	    default:
358	        printf("ERROR!\n");
359	        break;
360	    }
361	
362	    for (int i = 0; i < SCREEN_HEIGHT / 3; i++)
363	    {
364	        for (int j = 0; j < SCREEN_WIDTH / 3; j++)
365	        {
366	            x = j + x_value;
367	            y = i + y_value;
368	
369	            focal_x = (-0.5 + 0.5 / srceen_width + x * 1.0 / srceen_width) * (focal - camera_pos[2]) / f;
370	            focal_y = (-0.5 + 0.5 / screen_height + y * 1.0 / screen_height) * (focal - camera_pos[2]) / f;
371	            height = 0;
372	
373	            for (int a = -8; a < 9; a = a + 8)
374	            {
375	                int width = 0;
376	                for (int b = -8; b < 9; b = b + 8)
377	                {
378	                    float x_ = b - b / 2 + b / 2 * (rand_r(&seed) / float(RAND_MAX));
379	                    float y_ = a - a / 2 + a / 2 * (rand_r(&seed) / float(RAND_MAX));
380	                    sub_pixel = vec3 ((-0.5 + 0.5 / srceen_width + (x + x_) * 1.0 / srceen_width), (-0.5 + 0.5 / screen_height + (y + y_) * 1.0 / screen_height), -2.0f);
381	                    d = vec3(focal_x - sub_pixel[0], focal_y - sub_pixel[1], focal - sub_pixel[2]);
382	                    d = R * d;
383	
384	                    if (closest_intersection(sub_pixel, d, triangles, intersection, mirror_intersec, 0))
385	                    {
386	                        light_area = direct_light(intersection, seed);
387	                        if (intersection.is_mirror)
388	                        {
389	                            mirror_shadow = direct_light(mirror_intersec, seed);
390	                            light_area = 0.5f * (indirect_light + (light_area + mirror_shadow) / 2.0f);
391	                        }
392	                        else
393	                        {
394	                            light_area = 0.5f * (indirect_light + light_area);
395	                        }
396	                        pixel_colour = light_area * intersection.colour;
397	
398	                        original_img[width][height] = pixel_colour;
399	                    }
400	                    else
401	                        original_img[width][height] = black;
402	
403	                    anti_aliasing[j][i][area] = anti_aliasing[j][i][area] + original_img[width][height];
404	                    width++;
405	                }
406	                height++;
407	            }
408	
409	            anti_aliasing[j][i][area] = anti_aliasing[j][i][area] / vec3(9.0f, 9.0f, 9.0f);
410	
411	
412	            PutPixelSDL(screen, x, y, anti_aliasing[j][i][area]);
413	            anti_aliasing[j][i][area] = black;
414	        }
415	    }
416	    return NULL;
417	}
