419	bool closest_intersection(const vec3& start, const vec3& dir, const vector<Triangle>& triangles, Intersection& cloestIntersection, Intersection& mirIntersection, int light)
420	{
421	
422	    bool flag = false;
423	    float min = 0.0;
424	    int triangle_index, ignore = 1;
425	    vec3 v0, v1, v2;
426	    vec3 reflect_position, reflect_dir;
427	    Intersection reflect_intersec;
428	
429	    float t_front, u_front, v_front;
430	    if (RayTriangleIntersection(start, dir, FRONT_V0, FRONT_V1, FRONT_V2, t_front, u_front, v_front))
431	        ignore = 0;
432	
433	    for (size_t i = 0; i < triangles.size(); i++)
434	    {
435	        v0 = triangles[i].v0;
436	        v1 = triangles[i].v1;
437	        v2 = triangles[i].v2;
438	
439	        if (ignore == 1 && light == 0)
440	        {
441	            if (i <= 9)
442	            {
443	                float t_hit, u_hit, v_hit;
444	                if (RayTriangleIntersection(start, dir, v0, v1, v2, t_hit, u_hit, v_hit) && t_hit > 0.03f)
445	                {
446	                    if (!flag)
447	                    {
448	                        min = t_hit;
449	                        triangle_index = i;
450	                    }
451	                    flag = true;
452	                    if (min > t_hit)
453	                    {
454	                        min = t_hit;
455	                        triangle_index = i;
456	                    }
457	                }
458	            }
459	        }
460	        else if (ignore == 0 || light == 1)
461	        {
462	            float t_hit, u_hit, v_hit;
463	            if (RayTriangleIntersection(start, dir, v0, v1, v2, t_hit, u_hit, v_hit) && t_hit > 0.03f)
464	            {
465	                if (!flag)
466	                {
467	                    min = t_hit;
468	                    triangle_index = i;
469	                }
470	                flag = true;
471	                if (min > t_hit)
472	                {
473	                    min = t_hit;
474	                    triangle_index = i;
475	                }
476	            }
477	        }
478	    }
479	
480	    if (flag)
481	    {
482	        cloestIntersection.position = start + min * dir;
483	        cloestIntersection.distance = min;
484	        cloestIntersection.triangle_index = triangle_index;
485	        if (triangle_index == 4 || triangle_index == 5)
486	        {
487	            reflect_position = start + min * dir;
488	            reflect_dir = vec3(-dir[0], dir[1], dir[2]);
489	            if (mirror_intersection(reflect_position, reflect_dir, triangles, reflect_intersec))
490	            {
491	                cloestIntersection.colour = reflect_intersec.colour;
492	
493	                mirIntersection.triangle_index = reflect_intersec.triangle_index;
494	                mirIntersection.position = reflect_intersec.position;
495	                mirIntersection.distance = reflect_intersec.distance;
496	            }
497	            cloestIntersection.is_mirror = true;
498	        }
499	        else
500	        {
501	            mirIntersection.triangle_index = triangle_index;
502	            mirIntersection.position = start + min * dir;
503	            mirIntersection.distance = min;
504	            cloestIntersection.colour = triangles[triangle_index].color;
505	            cloestIntersection.is_mirror = false;
506	        }
507	        return true;
508	    }
509	    else
510	        return false;
511	}
