513	vec3 direct_light(const Intersection &point, unsigned int& seed)
514	{
515	    vec3 surface_light, dis, light_area, shadow_colour;
516	    float r;
517	    Intersection inter, shadow_inter, mirIntersection;
518	
519	    surface_light = light_pos - point.position;
520	    r = glm::length(surface_light);
521	    float result = surface_light[0] * triangles[point.triangle_index].normal[0] + surface_light[1] * triangles[point.triangle_index].normal[1] + surface_light[2] * triangles[point.triangle_index].normal[2];
522	    float area_divisor = 4.0 * 3.1415926 * r * r;
523	    if (result > 0.0)
524	        light_area = result / area_divisor * light_colour;
525	    else
526	        light_area = vec3(0.0, 0.0, 0.0);
527	
528	    if (light_pos[1] < -0.20f)
529	    {
530	        if (point.position[1] >= -0.20f)
531	        {
532	            if (closest_intersection(point.position, surface_light, triangles, inter, mirIntersection, 1))
533	            {
534	                dis = inter.position - point.position;
535	                if (r > glm::length(dis) && result > 0.0 && point.triangle_index != inter.triangle_index)
536	                {
537	                    light_area = vec3(0.0, 0.0, 0.0);
538	                    for (int i = 0; i < 10; i++)
539	                    {
540	                        vec3 direction = surface_light + vec3(0.03f * (((rand_r(&seed) / float(RAND_MAX)) - 0.5f) * 2.0f), 0.03f * (((rand_r(&seed) / float(RAND_MAX)) - 0.5f) * 2.0f), 0.03f * (((rand_r(&seed) / float(RAND_MAX)) - 0.5f) * 2.0f));
541	                        if (shadow_intersection(point.position, direction, inter.triangle_index, shadow_inter))
542	                            shadow_colour = vec3(0.0, 0.0, 0.0);
543	                        else
544	                            shadow_colour = triangles[point.triangle_index].color;
545	
546	                        light_area = light_area + shadow_colour;
547	                    }
548	                    light_area = light_area / vec3(10.0f, 10.0f, 10.0f);
549	                }
550	            }
551	        }
552	    }
553	    else
554	    {
555	        if (closest_intersection(point.position, surface_light, triangles, inter, mirIntersection, 1))
556	        {
557	            dis = inter.position - point.position;
558	            if (r > glm::length(dis) && result > 0.0 && point.triangle_index != inter.triangle_index)
559	            {
560	                light_area = vec3(0.0, 0.0, 0.0);
