static const vec3 FRONT_V0(-0.76f, -0.87f, -1.0f);
static const vec3 FRONT_V1(-0.76f,  1.0f,  -1.0f);
static const vec3 FRONT_V2( 1.31f,  1.0f,  -1.0f);

/* ----------------------------------------------------------------------------*/
/* FUNCTIONS                                                                   */
void Update();
