198	// ---------------------------------------------------------------------------
199	// shadow_intersect_gpu
200	// Tests a narrow band of triangles around `id` for any occlusion.
201	// ---------------------------------------------------------------------------
202	inline bool shadow_intersect_gpu(float3 orig,
203	                                 float3 dir,
204	                                 int    id,
205	                                 constant GPUTriangle* triangles,
206	                                 int triangle_count)
207	{
208	    int lo = max(0,              id - 2);
209	    int hi = min(triangle_count, id + 3);
210	
211	    for (int i = lo; i < hi; ++i) {
212	        float t = 0.0f;
213	        if (ray_triangle_intersect(orig, dir,
214	                                   triangles[i].v0.xyz,
215	                                   triangles[i].v1.xyz,
216	                                   triangles[i].v2.xyz,
217	                                   t))
218	        {
219	            if (t > 0.0f) return true;
220	        }
221	    }
222	    return false;
223	}
224	
225	// ---------------------------------------------------------------------------
226	// closest_intersect_gpu
227	// ---------------------------------------------------------------------------
228	inline GPUIntersection closest_intersect_gpu(float3 orig,
229	                                             float3 dir,
230	                                             constant GPUTriangle* triangles,
231	                                             int triangle_count,
232	                                             int light,              // 0 = normal, 1 = shadow ray
233	                                             constant RenderUniforms& uni)
234	{
235	    GPUIntersection result;
236	    result.distance       = 1e30f;
237	    result.triangle_index = -1;
238	    result.colour         = float3(0.0f);
239	    result.is_mirror      = false;
240	    result.position       = float3(0.0f);
241	
242	    // --- Triangle loop ---
243	    // Always test all triangles for primary and shadow rays.
244	    // The original CPU front-plane test caused seam blurring: AA jitter made
245	    // some sub-samples hit the front plane (ignore=0, all 30 tris) and others
246	    // miss it (ignore=1, only 10 tris), giving inconsistent results per pixel.
247	    for (int i = 0; i < triangle_count; ++i) {
248	        float t = 0.0f;
249	        if (ray_triangle_intersect(orig, dir,
250	                                   triangles[i].v0.xyz,
251	                                   triangles[i].v1.xyz,
252	                                   triangles[i].v2.xyz,
253	                                   t))
254	        {
255	            if (t > 0.03f && t < result.distance) {
256	                result.distance       = t;
257	                result.triangle_index = i;
258	                result.position       = orig + dir * t;
259	            }
260	        }
261	    }
262	
263	    // --- Post-process hit ---
264	    if (result.triangle_index >= 0) {
265	        int idx = result.triangle_index;
266	
267	        if (idx == 4 || idx == 5) {
268	            // Mirror surface: reflect and re-trace
269	            float3 reflect_dir = float3(-dir.x, dir.y, dir.z);
270	            GPUIntersection mirror_hit = mirror_intersect_gpu(result.position,
271	                                                              reflect_dir,
272	                                                              triangles,
273	                                                              triangle_count);
274	            result.colour    = mirror_hit.colour;
275	            result.is_mirror = true;
276	        } else {
277	            result.colour    = triangles[idx].color.xyz;
278	            result.is_mirror = false;
279	        }
280	    }
281	
282	    return result;
283	}
284	
285	// ---------------------------------------------------------------------------
286	// direct_light_gpu — area light sampling (stratified 2×2 = 4 samples)
287	// ---------------------------------------------------------------------------
288	constant int N_LIGHT_SAMPLES = 3;
289	
290	inline float3 direct_light_gpu(GPUIntersection        point,
291	                                constant GPUTriangle*  triangles,
292	                                int                    triangle_count,
293	                                constant RenderUniforms& uni,
294	                                thread uint&           seed)
295	{
296	    int    idx    = point.triangle_index;
297	    float3 normal = triangles[idx].normal.xyz;
298	    float3 light_n = uni.light_normal.xyz;
299	
300	    float3 accum = float3(0.0f);
301	
302	    // 3 stratified random samples on the rectangular area light
303	    for (int s = 0; s < N_LIGHT_SAMPLES; ++s) {
304	        int su = int(rand_float(seed) * 2.0f);
305	        int sv = int(rand_float(seed) * 2.0f);
306	        su = min(su, 1); sv = min(sv, 1);
307	        float3 sample_pos = sample_area_light(uni, seed, su, sv);
308	        float3 dir = sample_pos - point.position;
309	        float  r   = length(dir);
310	        float3 dir_n = dir / r;
311	
312	        // Cosine at surface
313	        float cos_surface = dot(dir_n, normal);
314	        if (cos_surface <= 0.0f) continue;
315	
316	        // Cosine at light (light normal points into scene = +y)
317	        float cos_light = dot(-dir_n, light_n);
318	        if (cos_light <= 0.0f) continue;
319	
320	        // Shadow test: trace from surface to light sample point
321	        GPUIntersection shadow = simple_intersect_gpu(point.position, dir,
322	                                                       triangles, triangle_count);
323	
324	        // Skip light geometry itself in shadow test
325	        bool blocked = (shadow.triangle_index >= 0) &&
326	                       (shadow.distance < 1.0f) &&
327	                       (shadow.triangle_index != idx) &&
328	                       (shadow.triangle_index < uni.light_tri_start);
329	
330	        if (blocked) continue;
331	
332	        // Area light contribution:
333	        // L = Le * cos_surface * cos_light * A / (N * π * r²)
334	        float geom = cos_surface * cos_light * uni.light_area_val /
335	                     (float(N_LIGHT_SAMPLES) * M_PI_F * r * r);
336	        accum += geom * uni.light_colour.xyz;
337	    }
338	
339	    return accum;
340	}
341	
342	// ---------------------------------------------------------------------------
343	// indirect_light_one_bounce — 1-bounce global illumination
344	// Shoots N_BOUNCES random cosine-weighted rays from the surface and averages.
345	// ---------------------------------------------------------------------------
346	constant int N_BOUNCES = 2;
347	
348	inline float3 indirect_light_one_bounce(GPUIntersection point,
349	                                         constant GPUTriangle* triangles,
350	                                         int triangle_count,
351	                                         constant RenderUniforms& uni,
352	                                         thread uint& seed,
353	                                         thread float& ao_factor)
354	{
355	    int idx = point.triangle_index;
356	    if (idx < 0) { ao_factor = 1.0f; return float3(0.0f); }
357	
358	    float3 normal = triangles[idx].normal.xyz;
359	    float3 accum = float3(0.0f);
360	    float ao_accum = 0.0f;
361	    float ao_radius = 0.6f; // AO sampling radius
362	
363	    for (int b = 0; b < N_BOUNCES; ++b) {
364	        float3 bounce_dir = cosine_weighted_hemisphere(normal, seed);
365	
366	        GPUIntersection bounce_hit = simple_intersect_gpu(point.position, bounce_dir,
367	                                                           triangles, triangle_count);
368	
369	        // AO: if hit is close, this point is occluded
370	        if (bounce_hit.triangle_index >= 0 && bounce_hit.distance < ao_radius) {
371	            ao_accum += 1.0f - (bounce_hit.distance / ao_radius);
372	        }
373	
374	        if (bounce_hit.triangle_index < 0) continue;
375	
376	        // Skip if bounce hit the light itself
377	        int bounce_idx = bounce_hit.triangle_index;
378	        if (bounce_idx >= uni.light_tri_start) continue;
379	
380	        float3 bounce_normal = triangles[bounce_idx].normal.xyz;
381	
382	        // Sample 1 random point on the area light for bounce illumination
383	        int su = int(rand_float(seed) * 2.0f);
384	        int sv = int(rand_float(seed) * 2.0f);
385	        su = min(su, 1); sv = min(sv, 1);
386	        float3 light_sample = sample_area_light(uni, seed, su, sv);
387	        float3 bounce_to_light = light_sample - bounce_hit.position;
388	        float bounce_r = length(bounce_to_light);
389	        float3 bounce_dir_n = bounce_to_light / bounce_r;
390	
391	        float bounce_cos_surface = dot(bounce_dir_n, bounce_normal);
392	        if (bounce_cos_surface <= 0.0f) continue;
393	
394	        float bounce_cos_light = dot(-bounce_dir_n, uni.light_normal.xyz);
395	        if (bounce_cos_light <= 0.0f) continue;
396	
397	        GPUIntersection shadow_test = simple_intersect_gpu(bounce_hit.position,
398	                                                            bounce_to_light,
399	                                                            triangles, triangle_count);
400	        if (shadow_test.triangle_index >= 0 &&
401	            shadow_test.distance < 1.0f &&
402	            shadow_test.triangle_index != bounce_idx &&
403	            shadow_test.triangle_index < uni.light_tri_start)
404	            continue;
405	
406	        // Area light formula for single sample
407	        float bounce_geom = bounce_cos_surface * bounce_cos_light * uni.light_area_val /
408	                            (M_PI_F * bounce_r * bounce_r);
409	        float3 bounce_direct = bounce_geom * uni.light_colour.xyz;
410	
411	        accum += triangles[bounce_idx].color.xyz * bounce_direct;
412	    }
413	
414	    // AO: 0 = fully occluded, 1 = fully open
415	    ao_factor = clamp(1.0f - 0.8f * ao_accum / float(N_BOUNCES), 0.30f, 1.0f);
416	
417	    // Clamp indirect to prevent fireflies
418	    float3 result = accum / float(N_BOUNCES);
419	    result = min(result, float3(0.35f));
420	    return result;
421	}
422	
423	// ---------------------------------------------------------------------------
424	// Kernel
425	// ---------------------------------------------------------------------------
426	kernel void raytracer_kernel(
427	    uint3                          gid            [[thread_position_in_grid]],
428	    constant GPUTriangle*          triangles      [[buffer(0)]],
429	    constant RenderUniforms&       uni            [[buffer(1)]],
430	    device   float4*               output_buffer  [[buffer(2)]])
431	{
432	    uint x          = gid.x;
433	    uint y          = gid.y;
434	    uint sample_idx = gid.z;
435	
436	    int sw = uni.screen_width;
437	    int sh = uni.screen_height;
438	
439	    if (x >= (uint)sw || y >= (uint)sh || sample_idx >= 9u) return;
440	
441	    // --- Seed --- use multiple PCG rounds for better decorrelation
442	    uint seed = pcg_hash(x + pcg_hash(y + pcg_hash(sample_idx + 1u)));
443	
444	    // --- Rotation matrix (yaw around Y axis) ---
445	    // GLM mat3 col-major: col0=(cos,0,-sin), col1=(0,1,0), col2=(sin,0,cos)
446	    // R*d = float3(cos*d.x + sin*d.z,  d.y,  -sin*d.x + cos*d.z)
447	    float yaw     = uni.yaw;
448	    float cos_yaw = cos(yaw);
449	    float sin_yaw = sin(yaw);
450	
451	    // --- Primary ray focal point ---
452	    float sw_f = float(sw);
453	    float sh_f = float(sh);
454	
455	    float focal_x = (-0.5f + 0.5f / sw_f + float(x) / sw_f)
456	                    * (uni.focal - uni.camera_pos.z) / uni.f;
457	    float focal_y = (-0.5f + 0.5f / sh_f + float(y) / sh_f)
458	                    * (uni.focal - uni.camera_pos.z) / uni.f;
459	
460	    // --- Anti-aliasing sub-sample grid (3×3, stratified jitter) ---
461	    int a_idx = int(sample_idx) / 3;   // 0, 1, 2
462	    int b_idx = int(sample_idx) % 3;   // 0, 1, 2
463	
464	    float x_ = -8.0f + (float(b_idx) + rand_float(seed)) * (16.0f / 3.0f);
465	    float y_ = -8.0f + (float(a_idx) + rand_float(seed)) * (16.0f / 3.0f);
466	
467	    // --- Sub-pixel position ---
468	    float3 sub_pixel = float3(
469	        -0.5f + 0.5f / sw_f + (float(x) + x_) / sw_f,
470	        -0.5f + 0.5f / sh_f + (float(y) + y_) / sh_f,
471	        -2.0f
472	    );
473	
474	    // --- Ray direction (before rotation) ---
475	    float3 d_local = float3(focal_x - sub_pixel.x,
476	                            focal_y - sub_pixel.y,
477	                            uni.focal - sub_pixel.z);
478	
479	    // Apply Y-axis rotation: R*d
480	    float3 d = float3(
481	         cos_yaw * d_local.x + sin_yaw * d_local.z,
482	         d_local.y,
483	        -sin_yaw * d_local.x + cos_yaw * d_local.z
484	    );
485	
486	    // --- Trace primary ray ---
487	    // Ray origin is sub_pixel (lens sample point at z=-2), NOT camera_pos (z=-3)
488	    // This matches the CPU code: closest_intersection(sub_pixel, d, ...)
489	    GPUIntersection intersection = closest_intersect_gpu(
490	        sub_pixel, d,
491	        triangles, uni.triangle_count,
492	        0, uni);
493	
494	    float3 pixel_colour = float3(0.0f);
495	
496	    if (intersection.triangle_index >= 0) {
497	        // If we hit a light source triangle, render emissive with glow
498	        if (intersection.triangle_index >= uni.light_tri_start) {
499	            // Light source center (in post-transform space)
500	            float3 light_center = uni.light_corner.xyz
501	                                + 0.5f * uni.light_edge_u.xyz
502	                                + 0.5f * uni.light_edge_v.xyz;
503	            float3 to_center = intersection.position - light_center;
504	            // Normalize distance by half-diagonal of the light rectangle
505	            float half_diag = 0.5f * length(uni.light_edge_u.xyz + uni.light_edge_v.xyz);
506	            float d_norm = length(to_center) / half_diag;
507	
508	            // Core emission: brighter in the center, slight falloff at edges
509	            float core = 1.0f - 0.25f * d_norm * d_norm;
510	            // Warm tint: center is slightly warm white
511	            float3 warm_white = float3(1.0f, 0.97f, 0.92f);
512	            pixel_colour = core * warm_white;
513	        } else {
514	        float3 light_area = direct_light_gpu(intersection,
515	                                             triangles,
516	                                             uni.triangle_count,
517	                                             uni,
518	                                             seed);
519	
520	        if (intersection.is_mirror) {
521	            // Mirror: also light the reflected surface and blend
522	            int mirror_idx = intersection.triangle_index;
523	
524	            // Build a temporary intersection at the mirror hit to light it
525	            // We already have the reflected colour in intersection.colour,
526	            // but we need a GPUIntersection pointing at the reflected surface.
527	            // Re-trace the reflected ray to get the proper surface intersection.
528	            float3 reflect_dir = float3(-d.x, d.y, d.z);
529	            GPUIntersection mirror_isec = mirror_intersect_gpu(
530	                intersection.position, reflect_dir,
531	                triangles, uni.triangle_count);
532	
533	            float3 mirror_shadow = float3(0.0f);
534	            if (mirror_isec.triangle_index >= 0) {
535	                mirror_shadow = direct_light_gpu(mirror_isec,
536	                                                 triangles,
537	                                                 uni.triangle_count,
538	                                                 uni,
539	                                                 seed);
540	            }
541	
542	            light_area = 0.22f * uni.indirect_light.xyz +
543	                                 (light_area + mirror_shadow) / 2.0f;
544	
545	            // Add indirect GI for the reflected surface
546	            if (mirror_isec.triangle_index >= 0) {
547	                float mirror_ao;
548	                float3 mirror_indirect = indirect_light_one_bounce(
549	                    mirror_isec, triangles, uni.triangle_count, uni, seed, mirror_ao);
550	                light_area += 0.35f * mirror_indirect;
551	            }
552	        } else {
553	            light_area = 0.22f * uni.indirect_light.xyz + light_area;
554	
555	            // Add 1-bounce indirect illumination (global illumination / colour bleeding)
556	            float ao;
557	            float3 indirect = indirect_light_one_bounce(
558	                intersection, triangles, uni.triangle_count, uni, seed, ao);
559	            light_area += 0.35f * indirect;
560	
561	            // Apply ambient occlusion
562	            light_area *= ao;
563	        }
564	
565	        pixel_colour = light_area * intersection.colour;
566	
567	        // --- Light glow on ceiling: edge-based bloom ---
568	        // Only ceiling triangles (index 6-7) get glow, based on distance
569	        // to the rectangular light EDGE (not center), so glow emanates from
570	        // the light boundary outward — like real light spilling from a panel.
571	        int hit_idx = intersection.triangle_index;
572	        if (hit_idx == 6 || hit_idx == 7) {
573	            float3 light_corner = uni.light_corner.xyz;
574	            float3 light_u = uni.light_edge_u.xyz;
575	            float3 light_v = uni.light_edge_v.xyz;
576	            float3 light_center = light_corner + 0.5f * light_u + 0.5f * light_v;
577	
578	            // Compute signed distance to rectangle in xz plane
579	            // Project hit point relative to light center onto u/v axes
580	            float3 rel = intersection.position - light_center;
581	            float half_u = 0.5f * length(light_u);
582	            float half_v = 0.5f * length(light_v);
583	            float3 u_dir = normalize(light_u);
584	            float3 v_dir = normalize(light_v);
585	
586	            float proj_u = dot(rel, u_dir);
587	            float proj_v = dot(rel, v_dir);
588	
589	            // Distance outside the rectangle on each axis (0 if inside)
590	            float du = max(abs(proj_u) - half_u, 0.0f);
591	            float dv = max(abs(proj_v) - half_v, 0.0f);
592	            float edge_dist = sqrt(du * du + dv * dv);
593	
594	            // Only apply glow OUTSIDE the light rectangle
595	            if (edge_dist > 0.0f) {
596	                // Tight glow falloff from edge — preserves rectangle shape
597	                float glow_sigma = 0.14f;
598	                float glow = 1.2f * exp(-edge_dist * edge_dist / (2.0f * glow_sigma * glow_sigma));
599	                // Wider subtle halo
600	                float halo_sigma = 0.40f;
601	                float halo = 0.10f * exp(-edge_dist * edge_dist / (2.0f * halo_sigma * halo_sigma));
602	
603	                float3 warm_glow = float3(1.0f, 0.97f, 0.92f);
604	                pixel_colour += (glow + halo) * warm_glow;
605	            }
606	        }
607	
608	        } // end non-light-triangle branch
609	    }
610	
611	    // --- Tone mapping (extended Reinhard with white point) + gamma correction ---
612	    float Lw = 2.5f; // slightly higher white point for brighter scene
613	    pixel_colour = pixel_colour * (1.0f + pixel_colour / (Lw * Lw)) / (1.0f + pixel_colour);
614	    pixel_colour = pow(clamp(pixel_colour, 0.0f, 1.0f), 1.0f / 2.2f);
615	
616	    // --- Write output ---
617	    uint out_idx = (y * uint(sw) + x) * 9u + sample_idx;
618	    output_buffer[out_idx] = float4(pixel_colour, 1.0f);
619	}
