1	#import <Metal/Metal.h>
2	#import <Foundation/Foundation.h>
3	#include <simd/simd.h>
4	#include <cstring>
5	#include <cstdio>
6	#include "MetalRenderer.h"
7	
8	// ---------------------------------------------------------------------------
9	// GPU structs – must match raytracer.metal exactly
10	// ---------------------------------------------------------------------------
11	struct GPUTriangle {
12	    simd_float4 v0, v1, v2, normal, color;
13	};
14	
15	struct RenderUniforms {
16	    simd_float4 camera_pos;
17	    simd_float4 light_pos;
18	    simd_float4 light_colour;
19	    simd_float4 indirect_light;
20	    simd_float4 light_corner;
21	    simd_float4 light_edge_u;
22	    simd_float4 light_edge_v;
23	    simd_float4 light_normal;
24	    float focal;
25	    float f;
26	    float yaw;
27	    float light_area_val;
28	    int triangle_count;
29	    int light_tri_start;
30	    int screen_width;
31	    int screen_height;
32	};
33	
34	// ---------------------------------------------------------------------------
35	// Helper: convert glm::vec3 → simd_float4 (w = 0)
36	// ---------------------------------------------------------------------------
37	static inline simd_float4 toFloat4(const glm::vec3& v) {
38	    return simd_make_float4(v.x, v.y, v.z, 0.0f);
39	}
40	
41	// ---------------------------------------------------------------------------
42	// Constructor
43	// ---------------------------------------------------------------------------
44	MetalRenderer::MetalRenderer(int width, int height)
45	    : _device(nullptr), _commandQueue(nullptr), _pipelineState(nullptr),
46	      _triangleBuffer(nullptr), _uniformsBuffer(nullptr), _outputBuffer(nullptr),
47	      _width(width), _height(height)
48	{
49	    @autoreleasepool {
50	        // 1. Create device & command queue
51	        id<MTLDevice> device = MTLCreateSystemDefaultDevice();
52	        if (!device) {
53	            fprintf(stderr, "[MetalRenderer] No Metal-capable GPU found.\n");
54	            return;
55	        }
56	        id<MTLCommandQueue> queue = [device newCommandQueue];
57	
58	        // 2. Locate raytracer.metallib
59	        NSString* path = [[NSBundle mainBundle] pathForResource:@"raytracer" ofType:@"metallib"];
60	
61	        if (!path) {
62	            // Try current working directory (running from Build/)
63	            NSString* cwd = [[NSFileManager defaultManager] currentDirectoryPath];
64	            NSString* candidate = [NSString stringWithFormat:@"%@/raytracer.metallib", cwd];
65	            if ([[NSFileManager defaultManager] fileExistsAtPath:candidate]) {
66	                path = candidate;
67	            }
68	        }
69	
70	        if (!path) {
71	            // Try directory containing the executable
72	            NSString* execPath = [[NSProcessInfo processInfo] arguments][0];
73	            NSString* execDir  = [execPath stringByDeletingLastPathComponent];
74	            NSString* candidate = [execDir stringByAppendingPathComponent:@"raytracer.metallib"];
75	            if ([[NSFileManager defaultManager] fileExistsAtPath:candidate]) {
76	                path = candidate;
77	            }
78	        }
79	
80	        if (!path) {
81	            fprintf(stderr, "[MetalRenderer] Could not find raytracer.metallib.\n");
82	            return;
83	        }
84	
85	        // 3. Load library
86	        NSError* err = nil;
87	        id<MTLLibrary> library = [device newLibraryWithURL:[NSURL fileURLWithPath:path]
88	                                                     error:&err];
89	        if (!library) {
90	            fprintf(stderr, "[MetalRenderer] Failed to load metallib: %s\n",
91	                    [[err localizedDescription] UTF8String]);
92	            return;
93	        }
94	
95	        // 4. Get compute kernel
96	        id<MTLFunction> fn = [library newFunctionWithName:@"raytracer_kernel"];
97	        if (!fn) {
98	            fprintf(stderr, "[MetalRenderer] Function 'raytracer_kernel' not found in metallib.\n");
99	            return;
100	        }
101	
102	        // 5. Build compute pipeline
103	        id<MTLComputePipelineState> pipeline =
104	            [device newComputePipelineStateWithFunction:fn error:&err];
105	        if (!pipeline) {
106	            fprintf(stderr, "[MetalRenderer] Failed to create pipeline: %s\n",
107	                    [[err localizedDescription] UTF8String]);
108	            return;
109	        }
110	
111	        // 6. Allocate persistent buffers
112	        id<MTLBuffer> uniformsBuf =
113	            [device newBufferWithLength:sizeof(RenderUniforms)
114	                                options:MTLResourceStorageModeShared];
115	
116	        // 9 samples per pixel, each sample is a float4
117	        NSUInteger outputBytes = (NSUInteger)width * height * 9 * sizeof(simd_float4);
118	        id<MTLBuffer> outputBuf =
119	            [device newBufferWithLength:outputBytes
120	                                options:MTLResourceStorageModeShared];
121	
122	        // 7. Store as void* (ARC bridge – we own the references)
123	        _device        = (__bridge_retained void*)device;
124	        _commandQueue  = (__bridge_retained void*)queue;
125	        _pipelineState = (__bridge_retained void*)pipeline;
126	        _uniformsBuffer = (__bridge_retained void*)uniformsBuf;
127	        _outputBuffer   = (__bridge_retained void*)outputBuf;
128	
129	        NSLog(@"Metal GPU renderer initialized: %@", device.name);
130	    }
131	}
132	
133	// ---------------------------------------------------------------------------
134	// Destructor
135	// ---------------------------------------------------------------------------
136	MetalRenderer::~MetalRenderer()
137	{
138	    @autoreleasepool {
139	        if (_outputBuffer)   { (void)(__bridge_transfer id<MTLBuffer>)_outputBuffer; }
140	        if (_uniformsBuffer) { (void)(__bridge_transfer id<MTLBuffer>)_uniformsBuffer; }
141	        if (_triangleBuffer) { (void)(__bridge_transfer id<MTLBuffer>)_triangleBuffer; }
142	        if (_pipelineState)  { (void)(__bridge_transfer id<MTLComputePipelineState>)_pipelineState; }
143	        if (_commandQueue)   { (void)(__bridge_transfer id<MTLCommandQueue>)_commandQueue; }
144	        if (_device)         { (void)(__bridge_transfer id<MTLDevice>)_device; }
145	    }
146	}
147	
148	// ---------------------------------------------------------------------------
149	// uploadTriangles
150	// ---------------------------------------------------------------------------
151	void MetalRenderer::uploadTriangles(const std::vector<Triangle>& tris)
152	{
153	    @autoreleasepool {
154	        id<MTLDevice> device = (__bridge id<MTLDevice>)_device;
155	        if (!device) return;
156	
157	        std::vector<GPUTriangle> gpuTris(tris.size());
158	        for (size_t i = 0; i < tris.size(); ++i) {
159	            gpuTris[i].v0     = toFloat4(tris[i].v0);
160	            gpuTris[i].v1     = toFloat4(tris[i].v1);
161	            gpuTris[i].v2     = toFloat4(tris[i].v2);
162	            gpuTris[i].normal = toFloat4(tris[i].normal);
163	            gpuTris[i].color  = toFloat4(tris[i].color);
164	        }
165	
166	        NSUInteger bytes = gpuTris.size() * sizeof(GPUTriangle);
167	        id<MTLBuffer> buf = [device newBufferWithBytes:gpuTris.data()
168	                                                length:bytes
169	                                               options:MTLResourceStorageModeShared];
170	
171	        // Release old buffer if present
172	        if (_triangleBuffer) {
173	            (void)(__bridge_transfer id<MTLBuffer>)_triangleBuffer;
174	        }
175	        _triangleBuffer = (__bridge_retained void*)buf;
176	    }
177	}
178	
179	// ---------------------------------------------------------------------------
180	// render
181	// ---------------------------------------------------------------------------
182	void MetalRenderer::render(const RenderParams& params, std::vector<glm::vec3>& pixels)
183	{
184	    @autoreleasepool {
185	        id<MTLDevice>                  device   = (__bridge id<MTLDevice>)_device;
186	        id<MTLCommandQueue>            queue    = (__bridge id<MTLCommandQueue>)_commandQueue;
187	        id<MTLComputePipelineState>    pipeline = (__bridge id<MTLComputePipelineState>)_pipelineState;
188	        id<MTLBuffer>                  triBuf   = (__bridge id<MTLBuffer>)_triangleBuffer;
189	        id<MTLBuffer>                  uniBuf   = (__bridge id<MTLBuffer>)_uniformsBuffer;
190	        id<MTLBuffer>                  outBuf   = (__bridge id<MTLBuffer>)_outputBuffer;
191	
192	        if (!device || !pipeline || !triBuf) {
193	            fprintf(stderr, "[MetalRenderer] render() called before initialisation or uploadTriangles().\n");
194	            return;
195	        }
196	
197	        // 1. Fill uniforms
198	        RenderUniforms uni;
199	        uni.camera_pos     = toFloat4(params.camera_pos);
200	        uni.light_pos      = toFloat4(params.light_pos);
201	        uni.light_colour   = toFloat4(params.light_colour);
202	        uni.indirect_light = toFloat4(params.indirect_light);
203	        uni.light_corner   = toFloat4(params.light_corner);
204	        uni.light_edge_u   = toFloat4(params.light_edge_u);
205	        uni.light_edge_v   = toFloat4(params.light_edge_v);
206	        uni.light_normal   = toFloat4(params.light_normal);
207	        uni.focal          = params.focal;
208	        uni.f              = params.f;
209	        uni.yaw            = params.yaw;
210	        uni.light_area_val = params.light_area;
211	        uni.triangle_count = (int)(triBuf.length / sizeof(GPUTriangle));
212	        uni.light_tri_start = params.light_tri_start;
213	        uni.screen_width   = params.screen_width;
214	        uni.screen_height  = params.screen_height;
215	
216	        // 2. Copy uniforms into shared buffer
217	        memcpy(uniBuf.contents, &uni, sizeof(RenderUniforms));
218	
219	        // 3. Encode compute pass
220	        id<MTLCommandBuffer>         cmdBuf  = [queue commandBuffer];
