1	#include <metal_stdlib>
2	using namespace metal;
3	
4	// ---------------------------------------------------------------------------
5	// Data structures
6	// ---------------------------------------------------------------------------
7	struct GPUTriangle {
8	    float4 v0;      // w unused
9	    float4 v1;
10	    float4 v2;
11	    float4 normal;
12	    float4 color;
13	};
14	
15	struct RenderUniforms {
16	    float4 camera_pos;
17	    float4 light_pos;
18	    float4 light_colour;
19	    float4 indirect_light;
20	    float4 light_corner;
21	    float4 light_edge_u;
22	    float4 light_edge_v;
23	    float4 light_normal;
24	    float  focal;
25	    float  f;
26	    float  yaw;
27	    float  light_area_val;
28	    int    triangle_count;
29	    int    light_tri_start;
30	    int    screen_width;
31	    int    screen_height;
32	};
33	
34	struct GPUIntersection {
35	    float3 position;
36	    float  distance;
37	    int    triangle_index;
38	    float3 colour;
39	    bool   is_mirror;
40	};
41	
42	// ---------------------------------------------------------------------------
43	// PCG-based random number generator (much better than LCG for spatial seeds)
44	// ---------------------------------------------------------------------------
45	inline uint pcg_hash(uint input) {
46	    uint state = input * 747796405u + 2891336453u;
47	    uint word  = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;
48	    return (word >> 22u) ^ word;
49	}
50	
51	inline uint lcg_rand(thread uint& seed) {
52	    seed = pcg_hash(seed);
53	    return seed;
54	}
55	
56	inline float rand_float(thread uint& seed) {
57	    return float(lcg_rand(seed)) / 4294967295.0f;
58	}
59	
60	// ---------------------------------------------------------------------------
61	// Möller–Trumbore ray-triangle intersection
62	// Returns true and writes t if the ray hits the triangle.
63	// ---------------------------------------------------------------------------
64	inline bool ray_triangle_intersect(float3 orig,
65	                                   float3 dir,
66	                                   float3 v0,
67	                                   float3 v1,
68	                                   float3 v2,
69	                                   thread float& t)
70	{
71	    const float epsilon = 1e-6f;
72	
73	    float3 e1 = v1 - v0;
74	    float3 e2 = v2 - v0;
75	
76	    float3 pvec = cross(dir, e2);
77	    float  det  = dot(e1, pvec);
78	
79	    if (abs(det) < epsilon) return false;
80	
81	    float  invDet = 1.0f / det;
82	    float3 tvec   = orig - v0;
83	
84	    float u = dot(tvec, pvec) * invDet;
85	    if (u < 0.0f || u > 1.0f) return false;
86	
87	    float3 qvec = cross(tvec, e1);
88	    float  v    = dot(dir, qvec) * invDet;
89	    if (v < 0.0f || u + v > 1.0f) return false;
90	
91	    t = dot(e2, qvec) * invDet;
92	    return t > 0.0f;
93	}
94	
95	// ---------------------------------------------------------------------------
96	// Cosine-weighted hemisphere sampling for diffuse bounce
97	// ---------------------------------------------------------------------------
98	inline float3 cosine_weighted_hemisphere(float3 normal, thread uint& seed) {
99	    float r1 = rand_float(seed);
100	    float r2 = rand_float(seed);
101	    float phi = 2.0f * M_PI_F * r1;
102	    float cos_theta = sqrt(1.0f - r2);
103	    float sin_theta = sqrt(r2);
104	
105	    // Build orthonormal basis (TBN) from normal
106	    float3 w = normal;
107	    float3 helper = abs(w.x) > 0.9f ? float3(0, 1, 0) : float3(1, 0, 0);
108	    float3 u = normalize(cross(helper, w));
109	    float3 v = cross(w, u);
110	
111	    return u * (cos(phi) * sin_theta) + v * (sin(phi) * sin_theta) + w * cos_theta;
112	}
113	
114	// ---------------------------------------------------------------------------
115	// Sample a random point on the rectangular area light (stratified 2×2)
116	// ---------------------------------------------------------------------------
117	inline float3 sample_area_light(constant RenderUniforms& uni,
118	                                 thread uint& seed,
119	                                 int stratum_u, int stratum_v)
120	{
121	    // Stratified: divide [0,1]² into 2×2 cells
122	    float u = (float(stratum_u) + rand_float(seed)) * 0.5f;
123	    float v = (float(stratum_v) + rand_float(seed)) * 0.5f;
124	    return uni.light_corner.xyz + u * uni.light_edge_u.xyz + v * uni.light_edge_v.xyz;
125	}
126	
127	// ---------------------------------------------------------------------------
128	// simple_intersect_gpu — lightweight closest-hit, no mirror logic
129	// Used for bounce rays and bounce shadow rays.
130	// ---------------------------------------------------------------------------
131	inline GPUIntersection simple_intersect_gpu(float3 orig,
132	                                             float3 dir,
133	                                             constant GPUTriangle* triangles,
134	                                             int triangle_count)
135	{
136	    GPUIntersection result;
137	    result.distance       = 1e30f;
138	    result.triangle_index = -1;
139	    result.colour         = float3(0.0f);
140	    result.is_mirror      = false;
141	    result.position       = float3(0.0f);
142	
143	    for (int i = 0; i < triangle_count; ++i) {
144	        float t = 0.0f;
145	        if (ray_triangle_intersect(orig, dir,
146	                                   triangles[i].v0.xyz,
147	                                   triangles[i].v1.xyz,
148	                                   triangles[i].v2.xyz,
149	                                   t))
150	        {
151	            if (t > 0.001f && t < result.distance) {
152	                result.distance       = t;
153	                result.triangle_index = i;
154	                result.position       = orig + dir * t;
155	                result.colour         = triangles[i].color.xyz;
156	            }
157	        }
158	    }
159	    return result;
160	}
161	
162	// ---------------------------------------------------------------------------
163	// mirror_intersect_gpu
164	// Scans all triangles and returns the closest hit (t > 0.03).
165	// ---------------------------------------------------------------------------
166	inline GPUIntersection mirror_intersect_gpu(float3 orig,
167	                                            float3 dir,
168	                                            constant GPUTriangle* triangles,
169	                                            int triangle_count)
170	{
171	    GPUIntersection result;
172	    result.distance       = 1e30f;
173	    result.triangle_index = -1;
174	    result.colour         = float3(0.0f);
175	    result.is_mirror      = false;
176	    result.position       = float3(0.0f);
177	
178	    for (int i = 0; i < triangle_count; ++i) {
179	        float t = 0.0f;
180	        if (ray_triangle_intersect(orig, dir,
181	                                   triangles[i].v0.xyz,
182	                                   triangles[i].v1.xyz,
183	                                   triangles[i].v2.xyz,
184	                                   t))
185	        {
186	            if (t > 0.001f && t < result.distance) {
187	                result.distance       = t;
188	                result.triangle_index = i;
189	                result.position       = orig + dir * t;
190	                result.colour         = triangles[i].color.xyz;
191	            }
192	        }
193	    }
194	
195	    return result;
196	}
197	
198	// ---------------------------------------------------------------------------
199	// shadow_intersect_gpu
200	// Tests ALL triangles for any occlusion.
201	// ---------------------------------------------------------------------------
202	inline bool shadow_intersect_gpu(float3 orig,
203	                                 float3 dir,
204	                                 int    id,
205	                                 constant GPUTriangle* triangles,
206	                                 int triangle_count)
207	{
208	    for (int i = 0; i < triangle_count; ++i) {
209	        float t = 0.0f;
210	        if (ray_triangle_intersect(orig, dir,
211	                                   triangles[i].v0.xyz,
212	                                   triangles[i].v1.xyz,
213	                                   triangles[i].v2.xyz,
214	                                   t))
215	        {
216	            if (t > 0.0f) return true;
217	        }
218	    }
219	    return false;
220	}
221	
222	// ---------------------------------------------------------------------------
223	// closest_intersect_gpu
224	// ---------------------------------------------------------------------------
225	inline GPUIntersection closest_intersect_gpu(float3 orig,
226	                                             float3 dir,
227	                                             constant GPUTriangle* triangles,
228	                                             int triangle_count,
229	                                             int light,              // 0 = normal, 1 = shadow ray
230	                                             constant RenderUniforms& uni)
231	{
232	    GPUIntersection result;
233	    result.distance       = 1e30f;
234	    result.triangle_index = -1;
235	    result.colour         = float3(0.0f);
236	    result.is_mirror      = false;
237	    result.position       = float3(0.0f);
238	
239	    // --- Triangle loop ---
240	    // Always test all triangles for primary and shadow rays.
241	    // The original CPU front-plane test caused seam blurring: AA jitter made
242	    // some sub-samples hit the front plane (ignore=0, all 30 tris) and others
243	    // miss it (ignore=1, only 10 tris), giving inconsistent results per pixel.
244	    for (int i = 0; i < triangle_count; ++i) {
245	        float t = 0.0f;
246	        if (ray_triangle_intersect(orig, dir,
247	                                   triangles[i].v0.xyz,
248	                                   triangles[i].v1.xyz,
249	                                   triangles[i].v2.xyz,
250	                                   t))
251	        {
252	            if (t > 0.03f && t < result.distance) {
253	                result.distance       = t;
254	                result.triangle_index = i;
255	                result.position       = orig + dir * t;
256	            }
257	        }
258	    }
259	
260	    // --- Post-process hit ---
261	    if (result.triangle_index >= 0) {
262	        int idx = result.triangle_index;
263	
264	        if (idx == 4 || idx == 5) {
265	            // Mirror surface: physically correct reflection  d - 2·dot(d,n)·n
266	            float3 n = triangles[idx].normal.xyz;
267	            float3 reflect_dir = dir - 2.0f * dot(dir, n) * n;
268	            GPUIntersection mirror_hit = mirror_intersect_gpu(result.position,
269	                                                              reflect_dir,
270	                                                              triangles,
271	                                                              triangle_count);
272	            result.colour    = mirror_hit.colour;
273	            result.is_mirror = true;
274	        } else {
275	            result.colour    = triangles[idx].color.xyz;
276	            result.is_mirror = false;
277	        }
278	    }
279	
280	    return result;
281	}
282	
283	// ---------------------------------------------------------------------------
284	// direct_light_gpu — area light sampling (stratified 2×2 = 4 samples)
285	// ---------------------------------------------------------------------------
286	constant int N_LIGHT_SAMPLES = 3;
287	
288	inline float3 direct_light_gpu(GPUIntersection        point,
289	                                constant GPUTriangle*  triangles,
290	                                int                    triangle_count,
291	                                constant RenderUniforms& uni,
292	                                thread uint&           seed)
293	{
294	    int    idx    = point.triangle_index;
295	    float3 normal = triangles[idx].normal.xyz;
296	    float3 light_n = uni.light_normal.xyz;
297	
298	    float3 accum = float3(0.0f);
299	
300	    // 3 stratified random samples on the rectangular area light
301	    for (int s = 0; s < N_LIGHT_SAMPLES; ++s) {
302	        int su = int(rand_float(seed) * 2.0f);
303	        int sv = int(rand_float(seed) * 2.0f);
304	        su = min(su, 1); sv = min(sv, 1);
305	        float3 sample_pos = sample_area_light(uni, seed, su, sv);
306	        float3 dir = sample_pos - point.position;
307	        float  r   = length(dir);
308	        float3 dir_n = dir / r;
309	
310	        // Cosine at surface
311	        float cos_surface = dot(dir_n, normal);
312	        if (cos_surface <= 0.0f) continue;
313	
314	        // Cosine at light (light normal points into scene = +y)
315	        float cos_light = dot(-dir_n, light_n);
316	        if (cos_light <= 0.0f) continue;
317	
318	        // Shadow test: trace from surface to light sample point
319	        GPUIntersection shadow = simple_intersect_gpu(point.position, dir,
320	                                                       triangles, triangle_count);
321	
322	        // Skip light geometry itself in shadow test
323	        bool blocked = (shadow.triangle_index >= 0) &&
324	                       (shadow.distance < 1.0f) &&
325	                       (shadow.triangle_index != idx) &&
326	                       (shadow.triangle_index < uni.light_tri_start);
327	
328	        if (blocked) continue;
329	
330	        // Area light contribution:
331	        // L = Le * cos_surface * cos_light * A / (N * π * r²)
332	        float geom = cos_surface * cos_light * uni.light_area_val /
333	                     (float(N_LIGHT_SAMPLES) * M_PI_F * r * r);
334	        accum += geom * uni.light_colour.xyz;
335	    }
336	
337	    return accum;
338	}
339	
340	// ---------------------------------------------------------------------------
341	// indirect_light_one_bounce — 1-bounce global illumination
342	// Shoots N_BOUNCES random cosine-weighted rays from the surface and averages.
343	// ---------------------------------------------------------------------------
344	constant int N_BOUNCES = 3;
345	
346	inline float3 indirect_light_one_bounce(GPUIntersection point,
347	                                         constant GPUTriangle* triangles,
348	                                         int triangle_count,
349	                                         constant RenderUniforms& uni,
350	                                         thread uint& seed,
351	                                         thread float& ao_factor)
352	{
353	    int idx = point.triangle_index;
354	    if (idx < 0) { ao_factor = 1.0f; return float3(0.0f); }
355	
356	    float3 normal = triangles[idx].normal.xyz;
357	    float3 accum = float3(0.0f);
358	    float ao_accum = 0.0f;
359	    float ao_radius = 0.6f; // AO sampling radius
360	
361	    for (int b = 0; b < N_BOUNCES; ++b) {
362	        float3 bounce_dir = cosine_weighted_hemisphere(normal, seed);
363	
364	        GPUIntersection bounce_hit = simple_intersect_gpu(point.position, bounce_dir,
365	                                                           triangles, triangle_count);
366	
367	        // AO: if hit is close, this point is occluded
368	        if (bounce_hit.triangle_index >= 0 && bounce_hit.distance < ao_radius) {
369	            ao_accum += 1.0f - (bounce_hit.distance / ao_radius);
370	        }
371	
372	        if (bounce_hit.triangle_index < 0) continue;
373	
374	        // Skip if bounce hit the light itself
375	        int bounce_idx = bounce_hit.triangle_index;
376	        if (bounce_idx >= uni.light_tri_start) continue;
377	
378	        float3 bounce_normal = triangles[bounce_idx].normal.xyz;
379	
380	        // Sample 1 random point on the area light for bounce illumination
381	        int su = int(rand_float(seed) * 2.0f);
382	        int sv = int(rand_float(seed) * 2.0f);
383	        su = min(su, 1); sv = min(sv, 1);
384	        float3 light_sample = sample_area_light(uni, seed, su, sv);
385	        float3 bounce_to_light = light_sample - bounce_hit.position;
386	        float bounce_r = length(bounce_to_light);
387	        float3 bounce_dir_n = bounce_to_light / bounce_r;
388	
389	        float bounce_cos_surface = dot(bounce_dir_n, bounce_normal);
390	        if (bounce_cos_surface <= 0.0f) continue;
391	
392	        float bounce_cos_light = dot(-bounce_dir_n, uni.light_normal.xyz);
393	        if (bounce_cos_light <= 0.0f) continue;
394	
395	        GPUIntersection shadow_test = simple_intersect_gpu(bounce_hit.position,
396	                                                            bounce_to_light,
397	                                                            triangles, triangle_count);
398	        if (shadow_test.triangle_index >= 0 &&
399	            shadow_test.distance < 1.0f &&
400	            shadow_test.triangle_index != bounce_idx &&
401	            shadow_test.triangle_index < uni.light_tri_start)
402	            continue;
403	
404	        // Area light formula for single sample
405	        float bounce_geom = bounce_cos_surface * bounce_cos_light * uni.light_area_val /
406	                            (M_PI_F * bounce_r * bounce_r);
407	        float3 bounce_direct = bounce_geom * uni.light_colour.xyz;
408	
409	        accum += triangles[bounce_idx].color.xyz * bounce_direct;
410	    }
411	
412	    // AO: 0 = fully occluded, 1 = fully open
413	    ao_factor = clamp(1.0f - 0.8f * ao_accum / float(N_BOUNCES), 0.30f, 1.0f);
414	
415	    // Clamp indirect to prevent fireflies (raised to preserve color bleeding)
416	    float3 result = accum / float(N_BOUNCES);
417	    result = min(result, float3(0.6f));
418	    return result;
419	}
420	
421	// ---------------------------------------------------------------------------
422	// Kernel
423	// ---------------------------------------------------------------------------
424	kernel void raytracer_kernel(
425	    uint3                          gid            [[thread_position_in_grid]],
426	    constant GPUTriangle*          triangles      [[buffer(0)]],
427	    constant RenderUniforms&       uni            [[buffer(1)]],
428	    device   float4*               output_buffer  [[buffer(2)]])
429	{
430	    uint x          = gid.x;
431	    uint y          = gid.y;
432	    uint sample_idx = gid.z;
433	
434	    int sw = uni.screen_width;
435	    int sh = uni.screen_height;
436	
437	    if (x >= (uint)sw || y >= (uint)sh || sample_idx >= 9u) return;
438	
439	    // --- Seed --- use multiple PCG rounds for better decorrelation
440	    uint seed = pcg_hash(x + pcg_hash(y + pcg_hash(sample_idx + 1u)));
441	
442	    // --- Rotation matrix (yaw around Y axis) ---
443	    // GLM mat3 col-major: col0=(cos,0,-sin), col1=(0,1,0), col2=(sin,0,cos)
444	    // R*d = float3(cos*d.x + sin*d.z,  d.y,  -sin*d.x + cos*d.z)
445	    float yaw     = uni.yaw;
446	    float cos_yaw = cos(yaw);
447	    float sin_yaw = sin(yaw);
448	
449	    // --- Primary ray focal point ---
450	    float sw_f = float(sw);
451	    float sh_f = float(sh);
452	
453	    float focal_x = (-0.5f + 0.5f / sw_f + float(x) / sw_f)
454	                    * (uni.focal - uni.camera_pos.z) / uni.f;
455	    float focal_y = (-0.5f + 0.5f / sh_f + float(y) / sh_f)
456	                    * (uni.focal - uni.camera_pos.z) / uni.f;
457	
458	    // --- Anti-aliasing sub-sample grid (3×3, stratified jitter) ---
459	    int a_idx = int(sample_idx) / 3;   // 0, 1, 2
460	    int b_idx = int(sample_idx) % 3;   // 0, 1, 2
461	
462	    float x_ = -8.0f + (float(b_idx) + rand_float(seed)) * (16.0f / 3.0f);
463	    float y_ = -8.0f + (float(a_idx) + rand_float(seed)) * (16.0f / 3.0f);
464	
465	    // --- Sub-pixel position ---
466	    float3 sub_pixel = float3(
467	        -0.5f + 0.5f / sw_f + (float(x) + x_) / sw_f,
468	        -0.5f + 0.5f / sh_f + (float(y) + y_) / sh_f,
469	        -2.0f
470	    );
471	
472	    // --- Ray direction (before rotation) ---
473	    float3 d_local = float3(focal_x - sub_pixel.x,
474	                            focal_y - sub_pixel.y,
475	                            uni.focal - sub_pixel.z);
476	
477	    // Apply Y-axis rotation: R*d
478	    float3 d = float3(
479	         cos_yaw * d_local.x + sin_yaw * d_local.z,
480	         d_local.y,
481	        -sin_yaw * d_local.x + cos_yaw * d_local.z
482	    );
483	
484	    // --- Trace primary ray ---
485	    // Ray origin is sub_pixel (lens sample point at z=-2), NOT camera_pos (z=-3)
486	    // This matches the CPU code: closest_intersection(sub_pixel, d, ...)
487	    GPUIntersection intersection = closest_intersect_gpu(
488	        sub_pixel, d,
489	        triangles, uni.triangle_count,
490	        0, uni);
491	
492	    float3 pixel_colour = float3(0.0f);
493	
494	    if (intersection.triangle_index >= 0) {
495	        // If we hit a light source triangle, render emissive with glow
496	        if (intersection.triangle_index >= uni.light_tri_start) {
497	            // Light source center (in post-transform space)
498	            float3 light_center = uni.light_corner.xyz
499	                                + 0.5f * uni.light_edge_u.xyz
500	                                + 0.5f * uni.light_edge_v.xyz;
501	            float3 to_center = intersection.position - light_center;
502	            // Normalize distance by half-diagonal of the light rectangle
503	            float half_diag = 0.5f * length(uni.light_edge_u.xyz + uni.light_edge_v.xyz);
504	            float d_norm = length(to_center) / half_diag;
505	
506	            // Core emission: brighter in the center, slight falloff at edges
507	            float core = 1.0f - 0.25f * d_norm * d_norm;
508	            // Warm tint: center is slightly warm white
509	            float3 warm_white = float3(1.0f, 0.97f, 0.92f);
510	            pixel_colour = core * warm_white;
511	        } else {
512	        float3 light_area = direct_light_gpu(intersection,
513	                                             triangles,
514	                                             uni.triangle_count,
515	                                             uni,
516	                                             seed);
517	
518	        if (intersection.is_mirror) {
519	            // Mirror: also light the reflected surface and blend
520	            int mirror_idx = intersection.triangle_index;
521	
522	            // Build a temporary intersection at the mirror hit to light it
523	            // We already have the reflected colour in intersection.colour,
524	            // but we need a GPUIntersection pointing at the reflected surface.
525	            // Re-trace the reflected ray to get the proper surface intersection.
526	            float3 mir_n = triangles[intersection.triangle_index].normal.xyz;
527	            float3 reflect_dir = d - 2.0f * dot(d, mir_n) * mir_n;
528	            GPUIntersection mirror_isec = mirror_intersect_gpu(
529	                intersection.position, reflect_dir,
530	                triangles, uni.triangle_count);
531	
532	            float3 mirror_shadow = float3(0.0f);
533	            if (mirror_isec.triangle_index >= 0) {
534	                mirror_shadow = direct_light_gpu(mirror_isec,
535	                                                 triangles,
536	                                                 uni.triangle_count,
537	                                                 uni,
538	                                                 seed);
539	            }
540	
541	            light_area = 0.22f * uni.indirect_light.xyz +
542	                                 (light_area + mirror_shadow) / 2.0f;
543	
544	            // Add indirect GI for the reflected surface
545	            if (mirror_isec.triangle_index >= 0) {
546	                float mirror_ao;
547	                float3 mirror_indirect = indirect_light_one_bounce(
548	                    mirror_isec, triangles, uni.triangle_count, uni, seed, mirror_ao);
549	                light_area += 0.5f * mirror_indirect;
550	            }
551	        } else {
552	            light_area = 0.22f * uni.indirect_light.xyz + light_area;
553	
554	            // Add 1-bounce indirect illumination (global illumination / colour bleeding)
555	            float ao;
556	            float3 indirect = indirect_light_one_bounce(
557	                intersection, triangles, uni.triangle_count, uni, seed, ao);
558	            light_area += 0.5f * indirect;
559	
560	            // Apply ambient occlusion
561	            light_area *= ao;
562	        }
563	
564	        pixel_colour = light_area * intersection.colour;
565	
566	        // --- Light glow on ceiling: edge-based bloom ---
567	        // Only ceiling triangles (index 6-7) get glow, based on distance
568	        // to the rectangular light EDGE (not center), so glow emanates from
569	        // the light boundary outward — like real light spilling from a panel.
570	        int hit_idx = intersection.triangle_index;
571	        if (hit_idx == 6 || hit_idx == 7) {
572	            float3 light_corner = uni.light_corner.xyz;
573	            float3 light_u = uni.light_edge_u.xyz;
574	            float3 light_v = uni.light_edge_v.xyz;
575	            float3 light_center = light_corner + 0.5f * light_u + 0.5f * light_v;
576	
577	            // Compute signed distance to rectangle in xz plane
578	            // Project hit point relative to light center onto u/v axes
579	            float3 rel = intersection.position - light_center;
580	            float half_u = 0.5f * length(light_u);
581	            float half_v = 0.5f * length(light_v);
582	            float3 u_dir = normalize(light_u);
583	            float3 v_dir = normalize(light_v);
584	
585	            float proj_u = dot(rel, u_dir);
586	            float proj_v = dot(rel, v_dir);
587	
588	            // Distance outside the rectangle on each axis (0 if inside)
589	            float du = max(abs(proj_u) - half_u, 0.0f);
590	            float dv = max(abs(proj_v) - half_v, 0.0f);
591	            float edge_dist = sqrt(du * du + dv * dv);
592	
593	            // Only apply glow OUTSIDE the light rectangle
594	            if (edge_dist > 0.0f) {
595	                // Tight glow falloff from edge — preserves rectangle shape
596	                float glow_sigma = 0.14f;
597	                float glow = 1.2f * exp(-edge_dist * edge_dist / (2.0f * glow_sigma * glow_sigma));
598	                // Wider subtle halo
599	                float halo_sigma = 0.40f;
600	                float halo = 0.10f * exp(-edge_dist * edge_dist / (2.0f * halo_sigma * halo_sigma));
601	
602	                float3 warm_glow = float3(1.0f, 0.97f, 0.92f);
603	                pixel_colour += (glow + halo) * warm_glow;
604	            }
605	        }
606	
607	        } // end non-light-triangle branch
608	    }
609	
610	    // --- Tone mapping: ACES Filmic approximation (Narkowicz 2015) + gamma ---
611	    // Better highlight rolloff and richer color saturation than Reinhard
612	    {
613	        float3 x = pixel_colour;
614	        float a = 2.51f;
615	        float b = 0.03f;
616	        float c = 2.43f;
617	        float dd = 0.59f;
618	        float e = 0.14f;
619	        pixel_colour = clamp((x * (a * x + b)) / (x * (c * x + dd) + e), 0.0f, 1.0f);
620	    }
621	    pixel_colour = pow(pixel_colour, 1.0f / 2.2f);
622	
623	    // --- Write output ---
624	    uint out_idx = (y * uint(sw) + x) * 9u + sample_idx;
625	    output_buffer[out_idx] = float4(pixel_colour, 1.0f);
626	}
