pixel_colour = light_area * intersection.colour;

// --- Light glow on ceiling: edge-based bloom ---
// Only ceiling triangles (index 6-7) get glow, based on distance
// to the rectangular light EDGE (not center), so glow emanates from
// the light boundary outward — like real light spilling from a panel.
int hit_idx = intersection.triangle_index;
if (hit_idx == 6 || hit_idx == 7) {
    float3 light_corner = uni.light_corner.xyz;
    float3 light_u = uni.light_edge_u.xyz;
    float3 light_v = uni.light_edge_v.xyz;
    float3 light_center = light_corner + 0.5f * light_u + 0.5f * light_v;

    // Compute signed distance to rectangle in xz plane
    // Project hit point relative to light center onto u/v axes
    float3 rel = intersection.position - light_center;
    float half_u = 0.5f * length(light_u);
    float half_v = 0.5f * length(light_v);
    float3 u_dir = normalize(light_u);
    float3 v_dir = normalize(light_v);

    float proj_u = dot(rel, u_dir);
    float proj_v = dot(rel, v_dir);

    // Distance outside the rectangle on each axis (0 if inside)
    float du = max(abs(proj_u) - half_u, 0.0f);
    float dv = max(abs(proj_v) - half_v, 0.0f);
    float edge_dist = sqrt(du * du + dv * dv);

    // Only apply glow OUTSIDE the light rectangle
    if (edge_dist > 0.0f) {
        // Tight glow falloff from edge — preserves rectangle shape
        float glow_sigma = 0.14f;
        float glow = 1.2f * exp(-edge_dist * edge_dist / (2.0f * glow_sigma * glow_sigma));
        // Wider subtle halo
        float halo_sigma = 0.40f;
        float halo = 0.10f * exp(-edge_dist * edge_dist / (2.0f * halo_sigma * halo_sigma));

        float3 warm_glow = float3(1.0f, 0.97f, 0.92f);
        pixel_colour += (glow + halo) * warm_glow;
    }
}

} // end non-light-triangle branch

